153→        assert!(msg.contains("Not found on PATH"));
154→    }
155→
156→    #[test]
157→    fn requirement_check_failed_displays_requirement_and_message() {
158→        let err = BivvyError::RequirementCheckFailed {
159→            requirement: "node".into(),
160→            message: "Install command exited with code 1".into(),
161→        };
162→        let msg = err.to_string();
163→        assert!(msg.contains("node"));
164→        assert!(msg.contains("Install command exited with code 1"));
165→    }
166→
167→    #[test]
168→    fn io_error_converts_from_std() {
169→        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
170→        let err: BivvyError = io_err.into();
171→        assert!(matches!(err, BivvyError::Io(_)));
172→    }
173→
174→    #[test]
175→    fn result_type_alias_works() {
176→        fn returns_error() -> Result<()> {
177→            Err(BivvyError::ConfigValidationError {
178→                message: "test".into(),
179→            })
180→        }
181→        assert!(returns_error().is_err());
182→    }
183→}
