 1→//! Bivvy - Interactive development environment setup automation.
 2→//!
 3→//! Bivvy is a CLI tool that replaces ad-hoc `bin/setup` scripts with
 4→//! declarative YAML configuration and a polished interactive CLI experience.
 5→//!
 6→//! # Modules
 7→//!
 8→//! - [`cli`] - Command-line interface and argument parsing
 9→//! - [`config`] - Configuration loading, parsing, and validation
10→//! - [`environment`] - Environment detection and resolution
11→//! - [`error`] - Error types and result aliases
12→//! - [`lint`] - Configuration validation and linting
13→//! - [`registry`] - Template registry and resolution
14→//! - [`runner`] - Step execution orchestration and dependency management
15→//! - [`shell`] - Shell command execution
16→//! - [`state`] - State management for execution history and preferences
17→//! - [`secrets`] - Secret detection and output masking
18→//! - [`steps`] - Step resolution and execution
19→//! - [`ui`] - Interactive prompts, spinners, and terminal output
20→//!
21→//! # Example
22→//!
23→//! ```
24→//! use bivvy::config::{InterpolationContext, resolve_string};
25→//!
26→//! // Resolve variables in a command
27→//! let mut ctx = InterpolationContext::new();
28→//! ctx.prompts.insert("mode".to_string(), "development".to_string());
29→//! let command = resolve_string("rails s -e ${mode}", &ctx).unwrap();
30→//! assert_eq!(command, "rails s -e development");
31→//! ```
32→//!
33→//! For file-based config loading, see the integration tests.
34→
35→pub mod cache;
36→pub mod cli;
37→pub mod config;
38→pub mod detection;
39→pub mod environment;
40→pub mod error;
41→pub mod feedback;
42→pub mod lint;
43→pub mod registry;
44→pub mod requirements;
45→pub mod runner;
46→pub mod secrets;
47→pub mod session;
48→pub mod shell;
49→pub mod state;
50→pub mod steps;
51→pub mod ui;
52→pub mod updates;
53→
54→pub use error::{BivvyError, Result};
55→

 1→//! Bivvy CLI entry point.
 2→
 3→use std::process::ExitCode;
 4→
 5→use bivvy::cli::{Cli, CommandDispatcher, Commands};
 6→use bivvy::shell::is_ci;
 7→use bivvy::ui::{create_ui, OutputMode};
 8→use clap::Parser;
 9→use tracing_subscriber::{fmt, prelude::*, EnvFilter};
10→
11→/// Initialize the tracing subscriber for logging.
12→///
13→/// Log level is controlled by:
14→/// 1. `--debug` flag sets level to DEBUG
15→/// 2. `RUST_LOG` environment variable (if set)
16→/// 3. Default is INFO
17→fn init_tracing(debug: bool) {
18→    let filter = if debug {
19→        EnvFilter::new("bivvy=debug")
20→    } else {
21→        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
22→    };
23→
24→    tracing_subscriber::registry()
25→        .with(fmt::layer().with_target(false))
26→        .with(filter)
27→        .init();
28→}
29→
30→fn main() -> ExitCode {
31→    let cli = Cli::parse();
32→    init_tracing(cli.debug);
33→
34→    tracing::debug!("Bivvy starting with args: {:?}", cli);
35→
36→    // Determine output mode
37→    let output_mode = if cli.quiet {
38→        OutputMode::Quiet
39→    } else if cli.verbose {
40→        OutputMode::Verbose
41→    } else {
42→        OutputMode::Normal
43→    };
44→
45→    // Handle --no-color
46→    if cli.no_color {
47→        std::env::set_var("NO_COLOR", "1");
48→    }
49→
50→    // Determine project root
51→    let project_root = cli
52→        .project
53→        .as_ref()
54→        .cloned()
55→        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
56→
57→    // Check if non-interactive (CI mode or explicit flag)
58→    let is_interactive = match &cli.command {
59→        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
60→        _ => !is_ci(),
61→    };
62→
63→    // Create UI
64→    let mut ui = create_ui(is_interactive, output_mode);
65→
66→    // Dispatch command
67→    let dispatcher = CommandDispatcher::new(project_root);
68→
69→    match dispatcher.dispatch(&cli, ui.as_mut()) {
70→        Ok(result) => ExitCode::from(result.exit_code as u8),
71→        Err(e) => {
72→            ui.error(&format!("Error: {}", e));
73→            ExitCode::from(1)
74→        }
75→    }
76→}
