  1→//! .env file parsing.
  2→//!
  3→//! This module provides functionality for parsing environment variable files
  4→//! in the standard KEY=value format.
  5→
  6→use anyhow::Result;
  7→use std::collections::HashMap;
  8→use std::path::Path;
  9→
 10→/// Parses .env files into a map of environment variables.
 11→///
 12→/// # Supported Formats
 13→///
 14→/// - Simple: `KEY=value`
 15→/// - Quoted: `KEY="value with spaces"` or `KEY='single quoted'`
 16→/// - Empty: `KEY=`
 17→/// - Comments: `# This is a comment`
 18→/// - Whitespace around equals: `KEY = value`
 19→/// - Values with equals signs: `URL=https://example.com?foo=bar`
 20→///
 21→/// # Example
 22→///
 23→/// ```
 24→/// use bivvy::config::EnvFileParser;
 25→///
 26→/// let content = r#"
 27→/// # Database config
 28→/// DATABASE_URL=postgres://localhost/db
 29→/// DEBUG="true"
 30→/// EMPTY=
 31→/// "#;
 32→///
 33→/// let vars = EnvFileParser::parse(content).unwrap();
 34→/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
 35→/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
 36→/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
 37→/// ```
 38→pub struct EnvFileParser;
 39→
 40→impl EnvFileParser {
 41→    /// Parse an env file content string into a map of variables.
 42→    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
 43→        let mut vars = HashMap::new();
 44→
 45→        for line in content.lines() {
 46→            let line = line.trim();
 47→
 48→            // Skip empty lines and comments
 49→            if line.is_empty() || line.starts_with('#') {
 50→                continue;
 51→            }
 52→
 53→            // Parse KEY=value
 54→            if let Some((key, value)) = Self::parse_line(line) {
 55→                vars.insert(key, value);
 56→            }
 57→        }
 58→
 59→        Ok(vars)
 60→    }
 61→
 62→    /// Parse a single line.
 63→    fn parse_line(line: &str) -> Option<(String, String)> {
 64→        let eq_pos = line.find('=')?;
 65→        let key = line[..eq_pos].trim().to_string();
 66→        let value = line[eq_pos + 1..].trim();
 67→
 68→        // Handle quoted values
 69→        let value = Self::unquote(value);
 70→
 71→        Some((key, value))
 72→    }
 73→
 74→    /// Remove surrounding quotes from a value.
 75→    fn unquote(value: &str) -> String {
 76→        if (value.starts_with('"') && value.ends_with('"'))
 77→            || (value.starts_with('\'') && value.ends_with('\''))
 78→        {
 79→            if value.len() >= 2 {
 80→                value[1..value.len() - 1].to_string()
 81→            } else {
 82→                value.to_string()
 83→            }
 84→        } else {
 85→            value.to_string()
 86→        }
 87→    }
 88→
 89→    /// Load and parse an env file from a path.
 90→    ///
 91→    /// # Example
 92→    ///
 93→    /// ```no_run
 94→    /// use bivvy::config::EnvFileParser;
 95→    /// use std::path::Path;
 96→    ///
 97→    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
 98→    /// for (key, value) in &vars {
 99→    ///     println!("{}={}", key, value);
100→    /// }
101→    /// ```
102→    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
103→        let content = std::fs::read_to_string(path)?;
104→        Self::parse(&content)
105→    }
106→
107→    /// Load and parse an env file, returning empty map if file doesn't exist.
108→    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
109→        if path.exists() {
110→            Self::load(path)
111→        } else {
112→            Ok(HashMap::new())
113→        }
114→    }
115→}
116→
