221→    fn load_optional_returns_empty_for_missing_file() {
222→        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));
223→
224→        assert!(result.is_ok());
225→        assert!(result.unwrap().is_empty());
