227→
228→    #[test]
229→    fn complex_env_file() {
230→        let content = r#"
231→# Application settings
232→APP_NAME=MyApp
233→DEBUG=true
234→
235→# Database
236→DATABASE_URL="postgres://user:pass@localhost:5432/db"
237→
238→# API Keys
239→API_KEY='secret-key-123'
240→WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
241→"#;
242→
243→        let vars = EnvFileParser::parse(content).unwrap();
244→
245→        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
246→        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
247→        assert_eq!(
248→            vars.get("DATABASE_URL"),
249→            Some(&"postgres://user:pass@localhost:5432/db".to_string())
250→        );
251→        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
252→        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
253→    }
254→}
