 18→/// Checks whether requirements are satisfied on the system.
 19→///
 20→/// Caches results per-run so the same requirement checked multiple times
 21→/// only executes commands once.
 22→pub struct GapChecker<'a> {
 23→    registry: &'a RequirementRegistry,
 24→    probe: &'a EnvironmentProbe,
 25→    project_root: PathBuf,
 26→    pub(crate) cache: HashMap<String, RequirementStatus>,
 27→}
 28→
 29→impl<'a> GapChecker<'a> {
 30→    /// Create a new gap checker.
 31→    pub fn new(
 32→        registry: &'a RequirementRegistry,
 33→        probe: &'a EnvironmentProbe,
 34→        project_root: &Path,
 35→    ) -> Self {
 36→        Self {
 37→            registry,
 38→            probe,
 39→            project_root: project_root.to_path_buf(),
 40→            cache: HashMap::new(),
 41→        }
 42→    }
 43→
 44→    /// Check all requirements for a step, returning only non-satisfied gaps.
 45→    ///
 46→    /// `provided_requirements` is authoritative — if the environment says
 47→    /// a requirement is provided, skip the check regardless of what the
 48→    /// step's requires list says. Until environments exist, callers pass `None`.
 49→    pub fn check_step(
 50→        &mut self,
 51→        step: &ResolvedStep,
 52→        provided: Option<&HashSet<String>>,
 53→    ) -> Vec<GapResult> {
 54→        let mut gaps = Vec::new();
 55→        for req_name in &step.requires {
 56→            if let Some(provided_set) = provided {
 57→                if provided_set.contains(req_name) {
 58→                    continue;
 59→                }
 60→            }
 61→
 62→            let status = self.check_one(req_name);
 63→            if !status.is_satisfied() {
 64→                gaps.push(GapResult {
 65→                    requirement: req_name.clone(),
 66→                    status,
 67→                });
 68→            }
 69→        }
 70→        gaps
 71→    }
 72→
 73→    /// Check a single requirement, using cache when available.
 74→    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
 75→        if let Some(cached) = self.cache.get(requirement) {
 76→            return cached.clone();
 77→        }
 78→
 79→        let status = self.evaluate(requirement);
 80→        self.cache.insert(requirement.to_string(), status.clone());
 81→        status
 82→    }
 83→
 84→    /// Invalidate a cached result for a specific requirement.
 85→    pub fn invalidate(&mut self, requirement: &str) {
 86→        self.cache.remove(requirement);
 87→    }
 88→
 89→    /// Invalidate all cached results.
 90→    pub fn invalidate_all(&mut self) {
 91→        self.cache.clear();
 92→    }
