        );

        // We need A's URL to exist for B's fetch, but it won't matter
        // because the cycle is detected before A is re-fetched
        let a_yaml = format!(
            r#"
extends:
  - url: {}
app_name: AppA
"#,
            server.url("/b.yml")
        );

        server.mock(|when, then| {
