 42→fn prompt_for_update(
 43→    ui: &mut dyn UserInterface,
 44→    info: &UpdateInfo,
 45→    method: &InstallMethod,
 46→) -> Result<bool> {
 47→    ui.message(&format!(
 48→        "A new version of bivvy is available: {} -> {}",
 49→        info.current, info.latest
 50→    ));
 51→
 52→    if !method.supports_auto_update() {
 53→        if let Some(url) = &info.release_url {
 54→            ui.message(&format!("Download from: {}", url));
 55→        }
 56→        return Ok(false);
 57→    }
 58→
 59→    let prompt = Prompt {
 60→        key: "update_bivvy".to_string(),
 61→        question: "Would you like to update now?".to_string(),
 62→        prompt_type: PromptType::Confirm,
 63→        default: Some("true".to_string()),
 64→    };
 65→
 66→    match ui.prompt(&prompt)? {
 67→        PromptResult::Bool(confirmed) => Ok(confirmed),
 68→        _ => Ok(false),
 69→    }
 70→}
