 73→fn execute_update(method: &InstallMethod) -> Result<()> {
 74→    let command = method
 75→        .update_command()
 76→        .ok_or_else(|| anyhow::anyhow!("No update command for install method"))?;
 77→
 78→    let parts: Vec<&str> = command.split_whitespace().collect();
 79→    if parts.is_empty() {
 80→        anyhow::bail!("Empty update command");
 81→    }
 82→
 83→    let status = Command::new(parts[0]).args(&parts[1..]).status()?;
 84→
 85→    if !status.success() {
 86→        anyhow::bail!("Update command failed with exit code: {:?}", status.code());
 87→    }
 88→
 89→    Ok(())
